mapper.select:
SELECT id, stage_id, title, type, content_type, external_url, platform, author, duration_minutes, description, sort_order, is_vip_only, status, view_count, created_at
FROM learning_units
WHERE id = #{id}

mapper.update:
UPDATE learning_units
SET view_count = view_count + 1
WHERE id = #{id}

mapper.delete:
DELETE lu FROM learning_units lu
JOIN path_stages ps ON lu.stage_id = ps.id
WHERE ps.path_id = #{pathId}

mapper.select:
SELECT COUNT(*) FROM learning_units lu
JOIN path_stages ps ON lu.stage_id = ps.id
WHERE ps.path_id = #{pathId}

SELECT id, stage_id, title, type, content_type, external_url, platform, author, duration_minutes, description, sort_order, is_vip_only, status, view_count, created_at
FROM learning_units
WHERE 1=1

    AND title LIKE CONCAT('%', #{keyword}, '%')


    AND type = #{type}


    AND platform = #{platform}

ORDER BY created_at DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM learning_units
WHERE 1=1

    AND title LIKE CONCAT('%', #{keyword}, '%')


    AND type = #{type}


    AND platform = #{platform}
